// ─── 子类型 ───
export interface Confusion { term: string; en: string; difference: string; }
export interface UseCase { title: string; description: string; visual?: string; }
export interface AnatomyItem { part: string; en: string; description: string; }
export interface Variant { name: string; en: string; description: string; visual?: string; }
export interface Scenario { title: string; visual: string; }
export interface Reference { title: string; url: string; }
export interface Quiz { question: string; options: { label: string; text: string }[]; answer: string; explanation: string; }

// ─── 术语条目 ───
export interface GlossaryTerm {
  id: string;
  name: string;
  en: string;
  explanation: string;
  analogy: string;
  scene: string;
  demo?: string;
  // 详情页扩展字段
  quote?: string;
  definition?: string;
  aliases?: string[];
  aiPrompt?: string;
  confusions?: Confusion[];
  whenToUse?: UseCase[];
  whenNotToUse?: UseCase[];
  anatomy?: AnatomyItem[];
  variants?: Variant[];
  scenarios?: Scenario[];
  references?: Reference[];
  quiz?: Quiz;
  preview?: string;
}

export interface GlossaryCategory {
  id: string;
  name: string;
  en: string;
  icon: string;
  color: string;
  description: string;
  terms: GlossaryTerm[];
}

