// ─── 查询辅助函数 ───
export function getTermBySlug(slug: string): { term: GlossaryTerm; category: GlossaryCategory } | null {
  for (const cat of glossaryData) {
    const term = cat.terms.find((t) => t.id === slug);
    if (term) return { term, category: cat };
  }
  return null;
}

export function getAllSlugs(): string[] {
  return glossaryData.flatMap((cat) => cat.terms.map((t) => t.id));
}

export function getAdjacentTerms(slug: string): { prev: GlossaryTerm | null; next: GlossaryTerm | null } {
  for (const cat of glossaryData) {
    const idx = cat.terms.findIndex((t) => t.id === slug);
    if (idx !== -1) {
      return {
        prev: idx > 0 ? cat.terms[idx - 1] : null,
        next: idx < cat.terms.length - 1 ? cat.terms[idx + 1] : null,
      };
    }
  }
  return { prev: null, next: null };
}
